package org.sigf.ui;
import javafx.scene.control.*;import javafx.scene.layout.*;import org.sigf.domain.*;import java.math.*;import java.util.*;import java.util.function.*;
/** Editable cart view; values are recalculated against the latest product grid. */
public final class CartView extends VBox {
 private final List<CartItem> items;private final Supplier<ReportGrid> products;private final BooleanSupplier locked;private final TableView<CartItem> table=new TableView<>();private final Label total=new Label();
 public CartView(List<CartItem> items,Supplier<ReportGrid> products,BooleanSupplier locked){this.items=items;this.products=products;this.locked=locked;setSpacing(7);table.setPrefHeight(145);table.setMinHeight(130);table.setPlaceholder(new Label("Agrega productos para comenzar."));table.setColumnResizePolicy(TableView.CONSTRAINED_RESIZE_POLICY_ALL_COLUMNS);column("Código",0);column("Producto",1);column("Cantidad",2);column("Precio sin IVA",3);column("Subtotal",4);getChildren().addAll(new Label("Carrito de venta"),table,total);refresh();}
 private void column(String label,int field){TableColumn<CartItem,String> c=new TableColumn<>(label);c.setCellValueFactory(v->new javafx.beans.property.ReadOnlyStringWrapper(value(v.getValue(),field)));c.setPrefWidth(field==1?260:110);table.getColumns().add(c);}
 private List<String> row(long id){ReportGrid grid=products.get();if(grid==null)return null;String key=Long.toString(id);return grid.rows().stream().filter(r->r.get(0).equals(key)).findFirst().orElse(null);}
 private String value(CartItem item,int field){List<String> row=row(item.productId());if(field==2)return Integer.toString(item.quantity());if(row==null)return field==1?"Producto "+item.productId():"";return switch(field){case 0->row.get(1);case 1->row.get(2);case 3->row.get(3);case 4->new BigDecimal(row.get(3)).multiply(BigDecimal.valueOf(item.quantity())).setScale(2).toPlainString();default->"";};}
 public void refresh(){table.getItems().setAll(items);table.refresh();BigDecimal sub=BigDecimal.ZERO,tax=BigDecimal.ZERO;boolean incomplete=false;for(CartItem item:items){List<String> row=row(item.productId());if(row==null||row.size()<8||row.get(7).isBlank()){incomplete=true;continue;}BigDecimal amount=new BigDecimal(row.get(3)).multiply(BigDecimal.valueOf(item.quantity()));sub=sub.add(amount);tax=tax.add(amount.multiply(new BigDecimal(row.get(7))).setScale(2,RoundingMode.HALF_UP));}total.setText(incomplete?"Hay productos sin clasificación de IVA; revise el catálogo.":"Subtotal: "+sub.setScale(2)+"  ·  IVA: "+tax.setScale(2)+"  ·  Total: "+sub.add(tax).setScale(2));}
 public void add(List<String> row){if(checkLocked())return;try{long id=Long.parseLong(row.get(0));quantity("Agregar · "+row.get(2),1,n->{int index=-1;for(int i=0;i<items.size();i++)if(items.get(i).productId()==id){index=i;break;}if(index<0)items.add(new CartItem(id,n));else items.set(index,new CartItem(id,Math.addExact(items.get(index).quantity(),n)));refresh();});}catch(Exception e){error(e);}}
 public void edit(){if(checkLocked())return;CartItem item=table.getSelectionModel().getSelectedItem();if(item==null){error(new IllegalArgumentException("Seleccione una línea del carrito"));return;}quantity("Cambiar cantidad",item.quantity(),n->{items.set(items.indexOf(item),new CartItem(item.productId(),n));refresh();});}
 public void remove(){if(checkLocked())return;CartItem item=table.getSelectionModel().getSelectedItem();if(item==null){error(new IllegalArgumentException("Seleccione una línea del carrito"));return;}items.remove(item);refresh();}
 private boolean checkLocked(){if(!locked.getAsBoolean())return false;error(new IllegalStateException("Resuelva primero la venta pendiente"));return true;}
 private static void quantity(String title,int initial,IntConsumer callback){TextInputDialog d=new TextInputDialog(Integer.toString(initial));d.setTitle(title);d.setHeaderText(title);d.setContentText("Cantidad:");d.showAndWait().ifPresent(value->{try{int n=Integer.parseInt(value);if(n<=0)throw new IllegalArgumentException("Cantidad inválida");callback.accept(n);}catch(Exception e){error(e);}});}
 private static void error(Throwable e){new Alert(Alert.AlertType.ERROR,Objects.toString(e.getMessage(),"Error inesperado"),ButtonType.OK).showAndWait();}
}
